import ipaddress
from functools import wraps

import six

from .commons import TRACE_STORE, DSP_RESOURCES, LOGGER
from .connection import get_connection
from .utils import get_hw_version, intlify
from .data_layer.message_handling import ReceiverThread, DispatcherThread
from .interfaces.basics import BasicsPublicInterface
from .interfaces.measurements import MeasurementsPublicInterface
from .interfaces.traces import TracesPublicInterface, ThroughputPublicInterface
from .interfaces.developer import DeveloperInterface


TARGET_PATH = '/home/ute/'
DEFAULT_ALIAS = 'default'


class Client(object):
    """
    A library providing selected functionalities available in DSP Explorer tool.
    """

    def __init__(self):
        self._connection = None
        self._receiver = None
        self._dispatcher = None

    @property
    def basics(self):
        return BasicsPublicInterface(self._connection)

    @property
    def traces(self):
        return TracesPublicInterface(self._connection)

    @property
    def throughput(self):
        return ThroughputPublicInterface(self._connection)

    @property
    def measurements(self):
        return MeasurementsPublicInterface(self._connection)

    @property
    def developer(self):
        return DeveloperInterface(self._connection)

    def check_connection(func):
        @wraps(func)
        def wrapper(self, *args, **kwargs):
            if not self._connection:
                raise RuntimeError('No connection, set up the library first!')
            return func(self, *args, **kwargs)
        return wrapper

    def set_up(self, bts_host='192.168.255.1', bts_port=15003, enable_extra_log=True):
        """
        Set up library.

        .. note::

            Within the setup, the HW version of MSM and ESM (if available) is automatically detected. However,
            for this detection to work properly, it is required that SSH connection to BTS is enabled, in particular,
            that ``systemAcctPermEnable`` is set to ``false`` in SCF.

        :param str bts_host: BTS ip address (192.168.255.1 is default)
        :param str bts_port: BTS port to connect to (15003 is default)
        :param str enable_extra_log: (Optional) If set to `${True}`, a special library log will be collected
            in ~/taf.sbts.browser_server_logs

        :return:
        """
        LOGGER.disabled = not enable_extra_log

        try:
            ipaddress.ip_address(six.ensure_text(bts_host))
        except (ValueError, ipaddress.AddressValueError):
            raise ValueError('Invalid bts_host: {}'.format(bts_host))

        bts_port = int(bts_port)
        msm, esm = get_hw_version()
        DSP_RESOURCES.set_resources(msm, esm)
        self._connection = get_connection(bts_host, bts_port)

        self._receiver = ReceiverThread(self._connection)
        self._receiver.start()

        self._dispatcher = DispatcherThread()
        self._dispatcher.start()

    def tear_down(self):
        """
        Tear down the library.
        """
        self.stop_all_traces()
        TRACE_STORE.remove_all()

        if self._connection:
            self._connection.close()

        if self._receiver:
            self._receiver.stop()

        if self._dispatcher:
            self._dispatcher.stop()

    @check_connection
    def get_rtt_value(self, cell_id):
        """
        Initialize IR measurements and return the round-trip time value (RTT)

        :param (str|int) cell_id: WCDMA cell id
        return: RTT value
        """
        return self.measurements.get_rtt_value(int(cell_id))

    @check_connection
    def start_hsupa_l2_trace(self, cell_id, trace_alias=DEFAULT_ALIAS):
        """
         Start collecting given trace

         .. note::
             Must go in pair with ``Stop Trace`` or ``Stop All Traces``

        :param str cell_id: WCDMA cell id
        :param str trace_alias: alias for trace collector
        """
        self.traces.start_hsupa_l2_trace(int(cell_id), trace_alias=trace_alias)

    @check_connection
    def start_cell_throughput(self, cell_id, trace_alias=DEFAULT_ALIAS):
        """
        Start cell throughput in UL.

        .. note::
            Must go in pair with ``Stop Trace`` or ``Stop All Traces``

        :param str cell_id: WCDMA cell id
        :param str trace_alias: alias for trace collector

        """
        self.throughput.start_cell_throughput(int(cell_id), trace_alias)

    @check_connection
    def stop_trace(self, trace_alias=DEFAULT_ALIAS):
        """
        Stop collecting traces specified by ``trace_alias``.

        :param str trace_alias: alias for trace collector
        """
        self.traces.stop_trace(trace_alias=trace_alias)

    @staticmethod
    def stop_all_traces():
        """
        Stop collecting all traces started with Start/Stop mechanism
        """
        for collector in TRACE_STORE:
            if not collector.stop_time:
                collector.stop()

    def save_trace(self, output_path, trace_alias=DEFAULT_ALIAS, as_zip=True):
        """
        Save file with traces specified by ``trace_alias``.

        :param str output_path: path where TXT or ZIP file with traces will be saved
        :param str trace_alias: alias for trace collector
        :param bool as_zip: True (default) or False
        return: path to saved file
        """
        return self.traces.save_trace(output_path, trace_alias=trace_alias, as_zip=as_zip)

    @check_connection
    def get_faraday_mode(self, board, cpu, humanize=True):
        """
        Get mode of a selected CPU.

        :param str board: board id, e.g., 0x12, 0x13
        :param str cpu: PU id, e.g., 0x31, 0x32, 0x81
        :param humanize: determines output format: as a simple integer (``False``),
            or as a descriptive string (``True``)
        """
        return self.basics.get_faraday_mode(board, cpu, humanize)

    @check_connection
    def get_dsp_mode(self, board, cpu, humanize=True):
        """
        Get mode of a selected CPU.

        :param str board: board id, e.g., 0x12, 0x13
        :param str cpu: PU id, e.g., 0x31, 0x32, 0x81
        :param humanize: determines output format: as a simple integer (``False``),
            or as a descriptive string (``True``)
        """
        return self.basics.get_dsp_mode(board, cpu, humanize)

    @check_connection
    def get_available_boards(self, as_hex=True):
        """
        Get a list of boards used by WCDMA
        """
        return self.basics.get_available_boards(as_hex)

    @check_connection
    def get_browser_sw_version(self, board, cpu):
        """
        Get version of WCDMA Signal Processing Software (WSP SW)

        :param str board: board id, e.g., 0x12, 0x13
        :param str cpu: PU id, e.g., 0x31, 0x32, 0x81
        return: a string with the version of WSP SW currently available on BTS
        """
        return self.developer.get_browser_sw_version(board, cpu)

    @check_connection
    def get_cell_ids(self, board, cpu):
        """
        Get a list of WCDMA cells handled by selected CPU

        :param str board: board id, e.g., 0x12, 0x13
        :param str cpu: PU id, e.g., 0x31, 0x32, 0x81
        """
        return self.developer.get_cell_ids(board, cpu)

    @check_connection
    def get_services(self, board, cpu, humanize=True):
        """
        Get a list of available services as tuples: (board, cpu, object_type, message_id, available_service)

        :param str board: board id, e.g., 0x12, 0x13
        :param str cpu: PU id, e.g., 0x31, 0x32, 0x81
        :param humanize: determines output format: service as a simple integer (``False``),
            or as a descriptive string (``True``)
        """
        return self.developer.get_services(board, cpu, humanize)

    @check_connection
    def get_user_ids(self, board, cpu):
        """
        Get a list of Users for a given CPU

        **Input parameters:**

        +----------------+------+----------------------------------+
        | Parameter name | Man. | Description                      |
        +================+======+==================================+
        | board          | Yes  | board id, e.g., 0x12, 0x13       |
        +----------------+------+----------------------------------+
        | cpu            | Yes  | CPU id, e.g., 0x31, 0x32, 0x81   |
        +----------------+------+----------------------------------+

        **Example:**

        .. code-block:: robotframework

            ${user_ids}=     Get User IDs     0x13    0x31
            ->  [7]
        """
        board, cpu = intlify(board, cpu)
        return self.developer.get_user_ids(board, cpu)

    @check_connection
    def get_hsupa_user_ids(self, board, cpu):
        """
        Get a list of HSUPA users for a given CPU

        **Input parameters:**

        +----------------+------+----------------------------------+
        | Parameter name | Man. | Description                      |
        +================+======+==================================+
        | board          | Yes  | board id, e.g., 0x12, 0x13       |
        +----------------+------+----------------------------------+
        | cpu            | Yes  | CPU id, e.g., 0x31, 0x32, 0x81   |
        +----------------+------+----------------------------------+

        **Example:**

        .. code-block:: robotframework

            ${hsupa_user_ids}=    Get HSUPA User IDs    0x13    0x31
            [7]
        """
        board, cpu = intlify(board, cpu)
        return self.developer.get_hsupa_user_ids(board, cpu)

    @check_connection
    def get_radio_link_ids(self, board, cpu):
        """
        Get a list of radio link IDs for a given CPU

        **Input parameters:**

        +----------------+------+----------------------------------+
        | Parameter name | Man. | Description                      |
        +================+======+==================================+
        | board          | Yes  | board id, e.g., 0x12, 0x13       |
        +----------------+------+----------------------------------+
        | cpu            | Yes  | CPU id, e.g., 0x31, 0x32, 0x81   |
        +----------------+------+----------------------------------+

        **Example:**

        .. code-block:: robotframework

            ${rl_ids}=    Get Radio Link IDs    0x13    0x31
            ->  [1]
        """
        board, cpu = intlify(board, cpu)
        return self.developer.get_radio_link_ids(board, cpu)
